# This file was generated by AI

import csv
import math
import statistics
import sys
from pathlib import Path
from typing import Any

if __package__ is None:
    sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from logger import get_logger

logger = get_logger(__name__)

DEFAULT_RESULTS_DIR = Path("bees_algorithm/results")

PART_A_ORDER = ["eil51", "berlin52", "st70", "eil76", "kroA100", "ch150"]
PART_B_ORDER = ["sphere", "rosenbrock", "rastrigin", "ackley"]


def _parse_bool(value: str) -> bool:
    return str(value).strip().lower() in {"true", "1", "yes"}


def _sample_std(values: list[float]) -> float:
    if len(values) < 2:
        return 0.0
    return statistics.stdev(values)


def _format_num(value: float) -> str:
    if not math.isfinite(value):
        return str(value)
    if value == 0.0:
        return "0.0000"
    abs_val = abs(value)
    if abs_val < 1e-3 or abs_val >= 1e5:
        return f"{value:.4e}"
    return f"{value:.4f}"


def summarize_tsp(
    results_dir: str | Path = DEFAULT_RESULTS_DIR,
) -> list[dict[str, Any]]:
    """
    Read part_a_tsp/raw/runs.csv and write summary_tsp.csv and summary_tsp.md.
    """
    base = Path(results_dir) / "part_a_tsp"
    runs_csv = base / "raw" / "runs.csv"
    if not runs_csv.exists():
        logger.warning(f"TSP runs file not found, skipping summary: {runs_csv}")
        return []

    with runs_csv.open("r", newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))

    if not rows:
        logger.warning("TSP runs.csv is empty; skipping summary.")
        return []

    grouped: dict[tuple[str, int, int, str], list[dict[str, str]]] = {}
    for row in rows:
        key = (
            row["instance"],
            int(row["cities"]),
            int(float(row["optimum"])),
            row["neighbourhood"],
        )
        grouped.setdefault(key, []).append(row)

    def _sort_key(item: tuple[str, int, int, str]) -> tuple[int, str, str]:
        inst, _, _, neigh = item
        rank = PART_A_ORDER.index(inst) if inst in PART_A_ORDER else len(PART_A_ORDER)
        return (rank, inst, neigh)

    summaries: list[dict[str, Any]] = []
    for instance, cities, optimum, neighbourhood in sorted(
        grouped.keys(), key=_sort_key
    ):
        group_rows = grouped[(instance, cities, optimum, neighbourhood)]
        valid_rows = [r for r in group_rows if _parse_bool(r["is_valid"])]
        metric_rows = valid_rows if valid_rows else group_rows

        final_bests = [float(r["final_best"]) for r in metric_rows]
        initial_bests = [
            float(r["initial_best"])
            for r in metric_rows
            if not math.isnan(float(r["initial_best"]))
        ]
        gaps = [float(r["gap_pct"]) for r in metric_rows]
        runtimes = [float(r["runtime_sec"]) for r in group_rows]

        summary = {
            "instance": instance,
            "cities": cities,
            "optimum": optimum,
            "neighbourhood": neighbourhood,
            "runs": len(group_rows),
            "valid_runs": len(valid_rows),
            "mean_initial_best": (
                statistics.mean(initial_bests) if initial_bests else float("nan")
            ),
            "best": min(final_bests),
            "mean": statistics.mean(final_bests),
            "std": _sample_std(final_bests),
            "mean_gap_pct": statistics.mean(gaps),
            "mean_runtime_sec": statistics.mean(runtimes),
        }
        summaries.append(summary)

    tables_dir = base / "tables"
    tables_dir.mkdir(parents=True, exist_ok=True)

    csv_fields = [
        "instance",
        "cities",
        "optimum",
        "neighbourhood",
        "runs",
        "valid_runs",
        "mean_initial_best",
        "best",
        "mean",
        "std",
        "mean_gap_pct",
        "mean_runtime_sec",
    ]
    csv_out = tables_dir / "summary_tsp.csv"
    with csv_out.open("w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=csv_fields)
        writer.writeheader()
        writer.writerows(summaries)

    md_lines = [
        "# Problem 1 Part A — TSP Summary (10 runs per instance/neighbourhood, 30,000 evals)",
        "",
        "| Instance | Cities | Optimum ($L^*$) | Neighbourhood | Valid Runs | Best | Mean | Std | Mean Gap (%) | Mean Runtime (s) |",
        "| :--- | ---: | ---: | :--- | :---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for s in summaries:
        md_lines.append(
            f"| {s['instance']} | {s['cities']} | {s['optimum']} | {s['neighbourhood']} "
            f"| {s['valid_runs']}/{s['runs']} | {s['best']:.0f} | {s['mean']:.2f} "
            f"| {s['std']:.2f} | {s['mean_gap_pct']:.2f}% | {s['mean_runtime_sec']:.3f} |"
        )
    md_out = tables_dir / "summary_tsp.md"
    md_out.write_text("\n".join(md_lines) + "\n", encoding="utf-8")

    logger.info(f"Wrote TSP summary tables: {csv_out} and {md_out}")
    return summaries


